<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1,maximum-scale=1,user-scalable=no,viewport-fit=cover"><title><?= htmlspecialchars($SITE_TITLE ?? 'MartPoint'); ?> — Sales Payments</title><link href="https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600;700&display=swap" rel="stylesheet"><link rel="stylesheet" href="<?= $theme_link; ?>css/font-awesome-4.7.0/css/font-awesome.min.css"><style>:root{--p:#0057ff;--bg:#f1f5f9;--text:#0f172a;--muted:#64748b;--border:#e2e8f0;--good:#059669;--bad:#dc2626}*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--text);font-family:Inter,-apple-system,BlinkMacSystemFont,sans-serif}.screen{min-height:100vh;padding:12px 16px 160px}.topbar{align-items:center;display:flex;gap:12px;margin-bottom:16px;padding-top:calc(8px + env(safe-area-inset-top,0px))}.back{color:var(--p);font-size:20px;text-decoration:none}.titles{flex:1;min-width:0}.store{color:var(--muted);font-size:11px;font-weight:600;letter-spacing:.4px;overflow:hidden;text-overflow:ellipsis;text-transform:uppercase;white-space:nowrap}h1{font-size:22px;margin:2px 0}.hint{background:#eff6ff;border:1px solid #bfdbfe;border-radius:14px;color:#1e40af;font-size:13px;line-height:1.5;margin-bottom:14px;padding:12px}.list{display:grid;gap:10px}.card{background:#fff;border:1px solid var(--border);border-radius:14px;padding:14px}.head{display:flex;gap:10px}.name{flex:1;font-size:15px;font-weight:700}.amount{color:var(--good);font-size:16px;font-weight:700}.sub{color:var(--muted);font-size:12px;line-height:1.45;margin-top:5px}.meta{align-items:center;border-top:1px solid var(--border);display:flex;justify-content:space-between;margin-top:11px;padding-top:10px}.tag{background:#eef2ff;border-radius:99px;color:#4338ca;font-size:11px;font-weight:700;padding:4px 8px}.delete{background:#fff;border:1px solid #fecaca;border-radius:9px;color:var(--bad);min-height:36px;min-width:38px}.empty{background:#fff;border:1px dashed var(--border);border-radius:14px;color:var(--muted);padding:30px 15px;text-align:center}</style></head><body><main class="screen"><header class="topbar"><a class="back" href="<?= base_url('mobile/more'); ?>"><i class="fa fa-chevron-left"></i></a><div class="titles"><div class="store"><?= htmlspecialchars($SITE_TITLE ?? 'MartPoint'); ?></div><h1>Sales Payments</h1></div></header><div class="hint"><i class="fa fa-info-circle"></i> Latest 100 receipts recorded against sales. New payments are collected from the invoice or Due Payments screen.</div><section class="list"><?php foreach($payments as $payment): ?><article class="card"><div class="head"><div class="name"><?= htmlspecialchars($payment->customer_name ?: 'Walk-in Customer'); ?><div class="sub"><?= htmlspecialchars($payment->sales_code ?: 'Sale unavailable'); ?> · <?= show_date($payment->payment_date); ?></div></div><div class="amount"><?= $this->currency(store_number_format($payment->payment)); ?></div></div><div class="meta"><span class="tag"><?= htmlspecialchars($payment->payment_type ?: 'Payment'); ?></span><?php if($can_delete): ?><button type="button" class="delete" onclick="removePayment(<?= (int)$payment->id; ?>)" aria-label="Delete payment"><i class="fa fa-trash"></i></button><?php endif; ?></div></article><?php endforeach; ?><?php if(empty($payments)): ?><div class="empty"><i class="fa fa-credit-card fa-2x"></i><p>No sales payments yet.</p></div><?php endif; ?></section></main><?php $this->load->view('mobile/bottom_nav',['active'=>'more']); ?><?php $this->load->view('mobile/mp_alert'); ?><?php $this->load->view('mobile/chat'); ?><script>function removePayment(id){if(!confirm('Delete this payment? The sale balance will be updated.'))return;var f=new FormData();f.append('payment_id',id);f.append('<?= $this->security->get_csrf_token_name(); ?>','<?= $this->security->get_csrf_hash(); ?>');fetch('<?= base_url('sales_payments/delete_payment'); ?>',{method:'POST',body:f,credentials:'same-origin'}).then(function(r){return r.text()}).then(function(r){if(r.trim()==='success'){location.reload();return}alert('Unable to delete this payment.');}).catch(function(){alert('Unable to delete this payment.');});}</script></body></html>
